#include <iostream>
#include <string>
#include <vector>

int main() {
    int number;
    std::cin >> number;
    std::string inputStr;
    std::cin >> inputStr;

    std::string tempStr = inputStr;
    std::string bracketsContent = "_";
    int startIdx = -1;
    int totalLength = static_cast<int>(tempStr.length());

    for (int index = 0; index < totalLength; ++index) {
        char ch = tempStr[index];
        if (ch == '(') {
            startIdx = index;
        } else if (ch == ')') {
            bracketsContent += tempStr.substr(startIdx + 1, index - startIdx - 1) + "_";
            tempStr = tempStr.substr(0, startIdx) + "_" + tempStr.substr(index + 1);
            totalLength = static_cast<int>(tempStr.length());
            index = startIdx - 1;
            startIdx = -1;
        }
    }

    // Count non-empty parts in bracketsContent
    int bracketCount = 0;
    size_t pos = 0;
    while ((pos = bracketsContent.find('_', pos)) != std::string::npos) {
        if (pos != 0 && bracketsContent[pos - 1] != '_') {
            // Count only non-empty segments
            bracketCount++;
        }
        ++pos;
    }
    // To handle the last segment if not empty
    if (bracketsContent.length() > 1 && bracketsContent.back() != '_') {
        bracketCount++;
    }

    // Split tempStr by '_'
    std::vector<std::string> segmentsArray;
    size_t start = 0;
    for (size_t i = 0; i <= tempStr.length(); ++i) {
        if (i == tempStr.length() || tempStr[i] == '_') {
            segmentsArray.push_back(tempStr.substr(start, i - start));
            start = i + 1;
        }
    }

    int maxSegmentLength = 0;
    for (const auto& segment : segmentsArray) {
        if (static_cast<int>(segment.length()) > maxSegmentLength) {
            maxSegmentLength = segment.length();
        }
    }

    std::cout << maxSegmentLength << " " << bracketCount << std::endl;

    return 0;
}
